/// <summary>
/// FFI-safe error type
/// </summary>
internal class CodeSearchException: UniffiException {
    CodeSearchException() : base() {}
    CodeSearchException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class Database : CodeSearchException {
        // Members
        public string @v1;

        // Constructor
        public Database(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class Runtime : CodeSearchException {
        // Members
        public string @v1;

        // Constructor
        public Runtime(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    

    
}

class FfiConverterTypeCodeSearchError : FfiConverterRustBuffer<CodeSearchException>, CallStatusErrorHandler<CodeSearchException> {
    public static FfiConverterTypeCodeSearchError INSTANCE = new FfiConverterTypeCodeSearchError();

    public override CodeSearchException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CodeSearchException.Database(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new CodeSearchException.Runtime(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCodeSearchError.Read()", value));
        }
    }

    public override int AllocationSize(CodeSearchException value) {
        switch (value) {

            case CodeSearchException.Database variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@v1);

            case CodeSearchException.Runtime variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@v1);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCodeSearchError.AllocationSize()", value));
        }
    }

    public override void Write(CodeSearchException value, BigEndianStream stream) {
        switch (value) {
            case CodeSearchException.Database variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@v1, stream);
                break;
            case CodeSearchException.Runtime variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@v1, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCodeSearchError.Write()", value));
        }
    }
}




class FfiConverterOptionalInt32: FfiConverterRustBuffer<int?> {
    public static FfiConverterOptionalInt32 INSTANCE = new FfiConverterOptionalInt32();

    public override int? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterInt32.INSTANCE.Read(stream);
    }

    public override int AllocationSize(int? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterInt32.INSTANCE.AllocationSize((int)value);
        }
    }

    public override void Write(int? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterInt32.INSTANCE.Write((int)value, stream);
        }
    }
}




